BEGIN;
INSERT INTO public.admin_users(id,email,password_hash,role,is_active) VALUES('f7500000-0000-4000-8000-000000000001','media-upload@example.test','test-only','admin',true);
INSERT INTO public.admin_sessions(id,admin_user_id,token_hash) VALUES('f7500000-0000-4000-8000-000000000002','f7500000-0000-4000-8000-000000000001',repeat('1',64));
DO $$ DECLARE actor uuid:='f7500000-0000-4000-8000-000000000001';sid uuid:='f7500000-0000-4000-8000-000000000002';t uuid;v jsonb;u uuid;f uuid;j public.delivery_jobs;doc jsonb;BEGIN
 IF has_function_privilege('anon','public.media_private_file(uuid,uuid,uuid,uuid)','EXECUTE') OR has_function_privilege('authenticated','public.finish_media_upload_scan(uuid,uuid,text,text,bigint,text,jsonb,text)','EXECUTE') THEN RAISE EXCEPTION 'Browser media upload access';END IF;
 INSERT INTO public.admin_teams(name,slug,created_by) VALUES('Fictional upload scope','fictional-upload-scope',actor) RETURNING id INTO t;
 doc:=jsonb_build_object('teamId',t,'folderId',NULL,'filename','fixture.png','mime','image/png','bytes',100,'sha256',repeat('a',64),'key','quarantine/'||gen_random_uuid()||'/'||gen_random_uuid());
 v:=public.mutate_media_upload(actor,sid,NULL,'create',doc,repeat('1',64),repeat('2',64),gen_random_uuid());u:=(v->>'uploadId')::uuid;f:=(v->>'fileId')::uuid;
 v:=public.mutate_media_upload(actor,sid,NULL,'create',doc,repeat('1',64),repeat('2',64),gen_random_uuid());
 IF(v->>'uploadId')::uuid<>u OR(SELECT count(*) FROM public.upload_intents WHERE media_id=f)<>1 THEN RAISE EXCEPTION 'Upload duplicated';END IF;
 BEGIN PERFORM public.media_private_file(actor,sid,f,gen_random_uuid());RAISE EXCEPTION 'Quarantine download';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 v:=public.mutate_media_upload(actor,sid,u,'complete','{}',repeat('3',64),repeat('2',64),gen_random_uuid());
 IF EXISTS(SELECT 1 FROM public.claim_worker_jobs(100,ARRAY['upload_scan']) WHERE payload->>'uploadId'=u::text) THEN RAISE EXCEPTION 'Old worker claimed media';END IF;
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['media_upload_scan']) WHERE payload->>'uploadId'=u::text;
 IF j.id IS NULL THEN RAISE EXCEPTION 'No media scan';END IF;
 PERFORM public.reserve_media_scan_object(j.id,j.lease_token);
 IF public.finish_media_upload_scan(j.id,gen_random_uuid(),'clean/'||u||'/'||gen_random_uuid(),'image/png',80,repeat('b',64),'{"width":10,"height":10}',NULL) THEN RAISE EXCEPTION 'Forged lease';END IF;
 UPDATE public.admin_sessions SET revoked_at=now() WHERE id=sid;
 IF public.finish_media_upload_scan(j.id,j.lease_token,'clean/'||u||'/'||j.lease_token,'image/png',80,repeat('b',64),'{"width":10,"height":10}',NULL) THEN RAISE EXCEPTION 'Revoked owner promoted';END IF;
 IF(SELECT state FROM public.upload_intents WHERE id=u)<>'rejected' OR(SELECT scan_state FROM public.media_files WHERE id=f)<>'rejected' THEN RAISE EXCEPTION 'Access change not rejected';END IF;
 UPDATE public.admin_sessions SET revoked_at=NULL WHERE id=sid;
 doc:=jsonb_set(doc,'{key}',to_jsonb('quarantine/'||gen_random_uuid()||'/'||gen_random_uuid()));
 v:=public.mutate_media_upload(actor,sid,NULL,'create',doc,repeat('4',64),repeat('2',64),gen_random_uuid());u:=(v->>'uploadId')::uuid;f:=(v->>'fileId')::uuid;
 v:=public.mutate_media_upload(actor,sid,u,'complete','{}',repeat('5',64),repeat('2',64),gen_random_uuid());
 SELECT * INTO j FROM public.claim_worker_jobs(100,ARRAY['media_upload_scan']) WHERE payload->>'uploadId'=u::text;
 PERFORM public.reserve_media_scan_object(j.id,j.lease_token);
 IF NOT public.finish_media_upload_scan(j.id,j.lease_token,'clean/'||u||'/'||j.lease_token,'image/png',80,repeat('b',64),'{"width":10,"height":10}',NULL) THEN RAISE EXCEPTION 'Clean promotion failed';END IF;
 v:=public.media_private_file(actor,sid,f,gen_random_uuid());
 IF v->>'mime'<>'image/png' OR v->>'filename'<>'fixture.png' OR(SELECT file_size FROM public.media_files WHERE id=f)<>80 OR(SELECT media_clean_sha256 FROM public.upload_intents WHERE id=u)<>repeat('b',64) THEN RAISE EXCEPTION 'Clean metadata wrong';END IF;
 BEGIN PERFORM public.mutate_media_upload(actor,sid,NULL,'create',jsonb_set(doc,'{bytes}','20971521'),repeat('6',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'Image exceeded cap';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_UPLOAD' THEN RAISE;END IF;END;
 BEGIN PERFORM public.mutate_media_upload(actor,sid,NULL,'create',jsonb_set(doc,'{mime}','"image/svg+xml"'),repeat('7',64),repeat('2',64),gen_random_uuid());RAISE EXCEPTION 'SVG accepted';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_UPLOAD' THEN RAISE;END IF;END;
END $$;
ROLLBACK;
